select case when monthly_fee >= 252 then 'HIGH' else 'LOW' end as monthly_fee_tier, count(case when plan = 'premium' then 1 end) as premium_count, max(monthly_fee) filter (where plan = 'premium') as premium_max_monthly_fee, count(*) filter (where status = 'PAUSED') as paused_rows from subscriptions group by case when monthly_fee >= 252 then 'HIGH' else 'LOW' end order by paused_rows;
